let state;try{state=JSON.parse(localStorage.getItem('life-saving-prototype-v1'))}catch{}
if(!state||!Array.isArray(state.assets)||!Array.isArray(state.platforms))state={assets:seedAssets(),platforms:seedPlatforms(),imported:[],history:[]};
let storageWarned=false;const save=()=>{try{localStorage.setItem('life-saving-prototype-v1',JSON.stringify(state))}catch{if(!storageWarned){toast('当前浏览器无法保存数据，关闭页面后变更可能丢失');storageWarned=true}}};
let activeFilter='在用',assetQuery='',importRows=null,importName='',importDone=null,compareResult=null,compareLoading=false,searchCounter=0;
const days=a=>Math.max(1,Math.floor((dateMs(a.end||today)-dateMs(a.start))/86400000)+1);
const net=a=>Math.max(0,a.price-(a.refund||0));
const daily=a=>net(a)/days(a);
const isActive=a=>a.status==='在用'&&a.start<=today;
const activeAssets=()=>state.assets.filter(isActive);
const totalDaily=()=>activeAssets().reduce((n,a)=>n+daily(a),0);
const costText=n=>n>0&&n<.01?'&lt; 0.01':money(n);
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),3000)}
function pageHead(k,title,sub,actions=''){return `<div class="page-head"><div><div class="overline">${k}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`}
const go=p=>{if(location.hash==='#'+p)render();else location.hash=p};
function currentPage(){let p=location.hash.slice(1);return ['assets','import','compare','platforms'].includes(p)?p:'assets'}
function render(){const p=currentPage();$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===p));$('#breadcrumb').innerHTML='工作台 <b>/</b> '+({assets:'资产总览',import:'导入账单',compare:'商品比价',platforms:'平台管理'}[p]);$('#today').textContent=today.replaceAll('-','.');({assets:renderAssets,import:renderImport,compare:renderCompare,platforms:renderPlatforms}[p])()}
function renderAssets(){const a=activeAssets(),total=a.reduce((n,a)=>n+net(a),0),d=totalDaily();const categories={};a.forEach(x=>categories[x.category]=(categories[x.category]||0)+net(x));const colors=['#496c4b','#94aa79','#c1cfa7','#e0e5d3','#bcae88'];let offset=0;const sorted=Object.entries(categories).sort((a,b)=>b[1]-a[1]);const gradient=sorted.map(([c,n],i)=>{const prev=offset;offset+=n/(total||1)*100;return `${colors[i%colors.length]} ${prev}% ${offset}%`}).join(',')||'#edf1e5 0% 100%';
$('#app').innerHTML=pageHead('MY EVERYDAY ASSETS','让每一件好物，都物有所值。','看清拥有的成本，把钱花在更值得的地方。',`<button class="btn" data-action="new-asset">＋ 手动添加</button><button class="btn primary" data-action="go-import">↥ 导入账单</button>`)+
`<div class="hero"><div><div class="eyebrow">A LITTLE LESS SPENDING. A LITTLE MORE LIVING.</div><h2>省钱，从了解你已经拥有的开始。</h2><p>物品陪伴你的每一天，都在让它变得更值得。</p></div><div class="hero-right"><strong>${a.length} 件好物</strong><span>正在陪你认真生活</span></div></div>
<div class="stats"><div class="stat"><span class="label">在用资产 · 买入净成本</span><span class="symbol">¥</span><div class="value"><small>¥</small> ${money(total)}</div><p>买入总价扣除已确认退款</p></div><div class="stat"><span class="label">持有日均成本</span><span class="symbol">↘</span><div class="value"><small>¥</small> ${money(d)}<small>/ 天</small></div><p>每天多使用一点，每日成本少一点</p></div><div class="stat"><span class="label">在用好物</span><span class="symbol">▦</span><div class="value">${a.length}<small>件</small></div><p>共记录 ${state.assets.length} 件生活物品</p></div></div>
<div class="content-grid"><div><div class="panel"><div class="panel-head"><h2>我的资产 <small>YOUR DAILY COMPANIONS</small></h2><button class="link" data-action="export-assets">导出清单 ↗</button></div><div class="filters"><div class="tabs">${['在用','未启用','已结束','全部'].map(x=>`<button class="${activeFilter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><input aria-label="搜索资产" placeholder="⌕ 搜索你的好物" id="asset-search" value="${esc(assetQuery)}"></div><div class="table-scroll"><table><thead><tr><th>物品 / 分类</th><th>买入净成本</th><th>持有天数</th><th>日均成本</th><th>状态</th><th></th></tr></thead><tbody id="asset-rows"></tbody></table></div><div class="panel-foot"><span id="asset-count"></span><span>点击物品，查看成本明细 →</span></div></div><p class="text-note">ⓘ 日均成本为各件在用物品的成本分摊之和，不代表每天实际现金支出。</p></div>
<div class="right-column"><div class="panel aside-panel"><h3>钱都花在哪里了？</h3><p>按在用资产买入净成本统计</p><div class="ring" style="background:conic-gradient(${gradient})"><div>${sorted.length}<small>生活分类</small></div></div>${sorted.map(([c,n],i)=>`<div class="legend"><span><i style="background:${colors[i%colors.length]}"></i>${esc(c)}</span><span>${(n/(total||1)*100).toFixed(0)}%</span></div>`).join('')||'<p class="subtitle">添加资产后查看分类占比</p>'}</div><div class="tip"><h3>✦ 今日省钱小想法</h3><p>${a.length?'下次想买新东西之前，先看看已经拥有的。真正省下的，是那些本来不必花的钱。':'从一件常用物品开始记录，了解你的第一笔生活成本。'}</p><button class="link" data-action="go-compare">去比较一件心仪好物 ↗</button></div></div></div>`;
renderAssetRows();$('#asset-search').addEventListener('input',e=>{assetQuery=e.target.value;renderAssetRows()});}
function renderAssetRows(){const rows=state.assets.filter(a=>(activeFilter==='全部'||(activeFilter==='在用'?isActive(a):activeFilter==='已结束'?['已售出','已报废','已退货'].includes(a.status):a.status==='未启用'||a.start>today))&&`${a.name} ${a.category}`.toLowerCase().includes(assetQuery.toLowerCase())).sort((a,b)=>daily(b)-daily(a));$('#asset-rows').innerHTML=rows.length?rows.map(a=>`<tr><td><button class="asset-cell" data-asset="${a.id}" style="text-align:left;padding:0"><span class="item-icon">${esc(a.icon||icons[a.category]||'◇')}</span><span><b>${esc(a.name)}</b><small>${esc(a.category)}</small></span></button></td><td>¥${money(net(a))}</td><td>${a.status==='未启用'||a.start>today?'—':days(a)+' 天'}</td><td class="cost">${a.status==='未启用'||a.start>today?'—':'¥'+costText(daily(a))+' <small>/ 天</small>'}</td><td><span class="pill ${a.status==='在用'?'':a.status==='未启用'?'amber':'gray'}">${esc(a.status)}</span></td><td><button class="dots" data-edit-asset="${a.id}" aria-label="编辑 ${esc(a.name)}">⋯</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty"><strong>这里还没有好物</strong>试试其他筛选，或添加你的第一件资产。</div></td></tr>`;$('#asset-count').textContent=`共 ${rows.length} 项 · 按日均成本排序`;}
let modalReturn=null;
function openModal(title,body,foot='',large=false){modalReturn=document.activeElement;const m=$('#modal');m.innerHTML=`<div class="dialog ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button data-action="close" aria-label="关闭">×</button></div>${body}${foot?`<div class="dialog-foot">${foot}</div>`:''}</div>`;m.hidden=false;document.body.style.overflow='hidden';setTimeout(()=>m.querySelector('input,button')?.focus(),0)}
function closeModal(){$('#modal').hidden=true;$('#modal').innerHTML='';document.body.style.overflow='';modalReturn?.focus?.()}
function assetDetail(id){const a=state.assets.find(x=>x.id===id);if(!a)return;openModal(esc(a.name),`<div class="dialog-body"><span class="pill">${esc(a.status)}</span><p class="subtitle" style="margin-top:15px">${a.end?'结束持有时':'当前'}日均成本</p><div class="detail-value">${a.status==='未启用'||a.start>today?'暂未启用':'¥'+costText(daily(a))+'<small style="font-size:13px"> / 天</small>'}</div><div class="formula">（买入 ¥${money(a.price)} − 退款 ¥${money(a.refund||0)}）÷ ${days(a)} 天<br>首日计 1 天 · 北京时间自然日${a.end?' · 已冻结至结束日':''}</div><div class="detail-grid"><div><span>买入净成本</span><b>¥${money(net(a))}</b></div><div><span>物品分类</span><b>${esc(a.category)}</b></div><div><span>开始使用日</span><b>${esc(a.start)}</b></div><div><span>结束持有日</span><b>${esc(a.end||'持续使用中')}</b></div></div><p class="subtitle">来源：${esc(a.source||'手动添加')}</p><p class="subtitle">${esc(a.note||'多使用一天，让每一笔花费更值得。')}</p></div>`,`<button class="btn danger" data-delete-asset="${a.id}">删除</button><button class="btn primary" data-edit-asset="${a.id}">编辑资产</button>`)}
function assetForm(id){const a=state.assets.find(a=>a.id===id)||{name:'',category:'数码电子',price:'',refund:0,start:today,status:'在用'};openModal(id?'编辑资产':'添加一件生活好物',`<form id="asset-form"><div class="dialog-body"><div class="field"><label for="name">物品名称</label><input id="name" name="name" maxlength="80" placeholder="例如：每天都在用的咖啡机" value="${esc(a.name)}" required></div><div class="form-grid"><div class="field"><label for="category">分类</label><select id="category" name="category">${Object.keys(icons).map(x=>`<option ${a.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="status">状态</label><select id="status" name="status">${['在用','未启用','已售出','已报废','已退货'].map(x=>`<option ${a.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="price">买入总价（元）</label><input id="price" name="price" type="number" min="0" max="99999999" step="0.01" value="${a.price}" required></div><div class="field"><label for="refund">已确认退款（元）</label><input id="refund" name="refund" type="number" min="0" step="0.01" value="${a.refund||0}" required></div><div class="field"><label for="start">开始使用日</label><input id="start" name="start" type="date" value="${esc(a.start)}" required></div><div class="field"><label for="end">结束日（结束持有时必填）</label><input id="end" name="end" type="date" max="${today}" value="${esc(a.end||'')}"></div></div><div class="field"><label for="note">备注（可选）</label><input id="note" name="note" maxlength="200" value="${esc(a.note||'')}" placeholder="记下这件好物的故事"></div><div id="form-error" class="error" role="alert"></div><p class="subtitle">修改后立即重算。未来启用的物品不计入当前成本。</p></div><div class="dialog-foot"><button type="button" class="btn" data-action="close">取消</button><button class="btn primary" type="submit">保存资产</button></div></form>`);$('#asset-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),p=Number(f.price),r=Number(f.refund),ended=['已售出','已报废','已退货'].includes(f.status);let err='';if(!f.name.trim())err='请输入物品名称';else if(!Number.isFinite(p)||!Number.isFinite(r)||p<0||r<0||r>p)err='退款不能超过买入总价，金额不能为负数';else if(!Number.isFinite(dateMs(f.start)))err='请选择有效的开始使用日';else if(ended&&(!f.end||f.end<f.start||f.end>today))err='结束日必填，且须在开始日与今天之间';if(err){$('#form-error').textContent=err;return}const next={...a,...f,name:f.name.trim(),price:Math.round(p*100)/100,refund:Math.round(r*100)/100,id:id||uid(),end:ended?f.end:undefined,status:!ended&&f.start>today?'未启用':f.status,source:a.source||'手动添加'};if(id)state.assets=state.assets.map(x=>x.id===id?next:x);else state.assets.push(next);save();closeModal();render();toast('已保存，日均成本已更新')};}
function csvRows(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw new Error('CSV 引号未闭合，请检查文件');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;}
const demoBill=()=>`交易号,交易时间,商品名称,金额,类型,分类\nDEMO-001,${shift(29)},小米台灯,199,资产,家用电器\nDEMO-002,${shift(12)},优衣库衬衫,149,资产,服饰鞋包\nDEMO-003,${shift(5)},午餐,32,消费,其他\nDEMO-004,${shift(3)},便利店消费,18.5,待确认,其他\nDEMO-005,${shift(2)},跑步背包,259,资产,运动户外\nDEMO-006,${shift(1)},金额待修正,,资产,其他`;
function download(name,text,type='text/csv;charset=utf-8'){const u=URL.createObjectURL(new Blob(['\ufeff',text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function prepareImport(text,name){try{const raw=csvRows(text.replace(/^\ufeff/,''));if(raw.length<2)throw Error('文件需要表头和至少一行交易');if(raw.length>5001)throw Error('原型最多导入 5,000 行，请拆分文件');const head=raw[0].map(x=>x.trim());const ix=(...names)=>head.findIndex(h=>names.includes(h));const fields={id:ix('交易号','id'),date:ix('交易时间','日期','date'),name:ix('商品名称','商品名','名称','name'),amount:ix('金额','amount'),type:ix('类型','type'),category:ix('分类','category')};if([fields.date,fields.name,fields.amount].some(i=>i<0))throw Error('缺少必填列：交易时间、商品名称、金额。请先下载模板。');const seen=new Set(state.imported||[]);importRows=raw.slice(1).map((r,i)=>{const date=(r[fields.date]||'').trim().slice(0,10),name=(r[fields.name]||'').trim(),amountRaw=(r[fields.amount]||'').trim(),amount=Number(amountRaw),sourceId=fields.id>=0?r[fields.id]?.trim():'',key=sourceId?'csv:'+sourceId:'csv:'+date+'|'+name+'|'+amount;let error='';if(!name)error='商品名为空';else if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(dateMs(date))||new Date(dateMs(date)+8*3600000).toISOString().slice(0,10)!==date||date>today)error='交易日期无效或晚于今天';else if(!amountRaw||!Number.isFinite(amount)||amount<=0)error='金额需大于 0；退款请到资产中编辑';const duplicate=seen.has(key);seen.add(key);const explicit=fields.type>=0?(r[fields.type]||'').trim():'';let kind=explicit==='资产'?'资产':explicit==='消费'?'消费':'待确认';if(!explicit){if(/台灯|耳机|手机|电脑|水壶|背包|鞋|衬衫|冰箱|椅|咖啡机/.test(name))kind='资产';else if(/午餐|晚餐|餐饮|地铁|打车|房租/.test(name))kind='消费'}return {row:i+2,date,name,amount,kind,key,error,duplicate,category:Object.keys(icons).includes(r[fields.category])?r[fields.category]:'其他'}});importName=name;importDone=null;renderImport()}catch(e){toast(e.message)}}
function renderImport(){const stage=importDone?3:importRows?2:1;$('#app').innerHTML=pageHead('BILL TO BELONGINGS','把账单，变成你的生活资产。','从一份账单开始，自动整理那些会陪伴你很久的好物。')+`<div class="steps">${['上传账单','预览与确认','导入完成'].map((x,i)=>`<div class="step ${stage>=i+1?'active':''}"><b>${stage>i+1?'✓':i+1}</b>${x}</div>`).join('')}</div>`;
if(importDone){$('#app').innerHTML+=`<div class="panel pad" style="text-align:center;padding:45px"><div class="upload-icon">✓</div><h2>你的生活账本，又完整了一点。</h2><p class="subtitle">已处理 ${importDone.total} 条交易，新增 ${importDone.created} 件资产。</p><div class="preview-summary" style="justify-content:center;margin:25px 0"><div><b>${importDone.created}</b><span>新增资产</span></div><div><b>${importDone.consumed}</b><span>普通消费</span></div><div><b>${importDone.skipped}</b><span>重复 / 失败 / 跳过</span></div></div><button class="btn primary" data-action="go-assets">查看我的资产 →</button><button class="btn" data-action="new-import" style="margin-left:10px">继续导入</button><p class="caption subtitle" style="margin-top:20px">待确认项已按你在预览中的选择处理；跳过的条目可修正后重导。</p></div>`;return}
if(importRows){const errors=importRows.filter(r=>r.error).length,dup=importRows.filter(r=>!r.error&&r.duplicate).length,valid=importRows.filter(r=>!r.error&&!r.duplicate);$('#app').innerHTML+=`<div class="notice">规则识别为原型演示，不使用真实 AI 服务。请核对每行分类，尤其是“待确认”条目；勾选确认后才会创建资产。</div><div class="panel"><div class="panel-head"><h2>确认导入内容 <small>${esc(importName)}</small></h2><button class="link" data-action="new-import">重新上传</button></div><div class="preview-summary"><div><b>${importRows.length}</b><span>总行数</span></div><div><b>${valid.length}</b><span>有效</span></div><div><b>${dup}</b><span>重复</span></div><div><b>${errors}</b><span>错误</span></div></div><div class="table-scroll"><table><thead><tr><th>行号</th><th>商品 / 日期</th><th>金额</th><th>处理方式</th><th>状态</th></tr></thead><tbody>${importRows.map((r,i)=>`<tr><td>${r.row}</td><td>${esc(r.name)}<br><span class="subtitle" style="font-size:10px">${esc(r.date)}</span></td><td>¥${money(r.amount||0)}</td><td>${r.error||r.duplicate?'—':`<select aria-label="第 ${r.row} 行处理方式" data-import-row="${i}" style="font-size:11px;padding:6px"><option value="资产" ${r.kind==='资产'?'selected':''}>加入资产</option><option value="消费" ${r.kind==='消费'?'selected':''}>普通消费</option><option value="待确认" ${r.kind==='待确认'?'selected':''}>待确认 · 跳过</option></select>`}</td><td><span class="pill ${r.error||r.duplicate||r.kind==='待确认'?'amber':''}">${esc(r.error|| (r.duplicate?'重复 · 跳过':r.kind==='待确认'?'需人工确认':'可导入'))}</span></td></tr>`).join('')}</tbody></table></div><div class="pad"><label class="checkbox"><input type="checkbox" id="confirm-import">我已核对分类，同意将“加入资产”的交易写入本地资产清单</label><div class="actions"><button class="btn primary" data-action="confirm-import" ${!valid.length?'disabled':''}>确认导入</button><button class="btn" data-action="download-errors">下载处理报告</button></div><p class="subtitle" style="margin-top:12px">导入使用交易号去重；没有交易号时按日期、名称、金额组合判重。原型暂不处理组合订单与自动退款关联。</p></div></div>`;return}
$('#app').innerHTML+=`<div class="import-grid"><div class="panel"><div class="panel-head"><h2>导入你的账单</h2><span class="pill">CSV 原型版</span></div><div class="upload-box" id="drop-zone"><div class="upload-icon">↥</div><h3>把账单拖到这里</h3><p>或者选择一份 CSV 文件，预览后再确认导入</p><button class="btn primary" data-action="choose-file">选择账单文件</button><input type="file" accept=".csv,text/csv" id="bill-file" hidden><small>仅支持 UTF-8 CSV · 最大 5 MB / 5,000 行<br>XLSX、支付平台原生模板映射尚未实现</small></div><div class="panel-foot"><span>第一次体验？用示例账单走一遍。</span><button class="link" data-action="demo-import">体验示例导入 →</button></div></div><div><div class="panel pad"><h3>一份账单，三步整理</h3><ol class="list-note"><li>识别商品、日期与金额</li><li>核对资产与普通消费</li><li>自动加入资产并计算成本</li></ol><button class="btn small" data-action="download-template">↓ 下载 CSV 模板</button></div><div class="tip" style="margin-top:18px"><h3>⌁ 你的数据，留在这里。</h3><p>文件只在当前浏览器解析，不上传到服务器。原型适合使用脱敏账单试体验。</p></div></div></div>${state.history.length?`<div class="panel" style="margin-top:22px"><div class="panel-head"><h2>最近导入</h2></div>${state.history.slice(-4).reverse().map(h=>`<div class="panel-foot"><span>${esc(h.name)} · ${esc(h.date)}</span><span>新增 ${h.count} 件资产</span></div>`).join('')}</div>`:''}`;const input=$('#bill-file');input.onchange=()=>loadFile(input.files[0]);const drop=$('#drop-zone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');loadFile(e.dataTransfer.files[0])};}
async function loadFile(f){if(!f)return;if(!f.name.toLowerCase().endsWith('.csv'))return toast('原型目前仅支持 CSV，请下载模板');if(f.size>5*1024*1024)return toast('文件需小于 5 MB');try{prepareImport(await f.text(),f.name)}catch{toast('文件读取失败，请重试')}}
function confirmImport(){if(!$('#confirm-import')?.checked)return toast('请先勾选核对确认');const valid=importRows.filter(r=>!r.error&&!r.duplicate),create=valid.filter(r=>r.kind==='资产'),consumed=valid.filter(r=>r.kind==='消费');create.forEach(r=>state.assets.push({id:uid(),name:r.name,category:r.category,price:Math.round(r.amount*100)/100,refund:0,start:r.date,status:'在用',source:'CSV · '+importName}));state.imported=[...new Set([...(state.imported||[]),...valid.filter(r=>r.kind!=='待确认').map(r=>r.key)])];state.history.push({name:importName,date:today,count:create.length});importDone={total:importRows.length,created:create.length,consumed:consumed.length,skipped:importRows.length-create.length-consumed.length};save();renderImport();toast('导入完成，资产已加入清单')}
function productArt(key){const drawings={airpods:'<rect x="51" y="75" width="138" height="76" rx="30" fill="#fafbf7" stroke="#b7c3b0" stroke-width="2"/><path d="M53 98h134" stroke="#d5ddcd" stroke-width="2"/><circle cx="120" cy="127" r="2" fill="#7a9975"/><g fill="#fff" stroke="#b7c3b0" stroke-width="2"><path d="M83 35c-14-3-24 4-24 15 0 10 8 15 17 16v23a7 7 0 0014 0V49c0-7-1-12-7-14z"/><path d="M157 35c14-3 24 4 24 15 0 10-8 15-17 16v23a7 7 0 01-14 0V49c0-7 1-12 7-14z"/></g><ellipse cx="72" cy="50" rx="4" ry="7" fill="#67816b"/><ellipse cx="168" cy="50" rx="4" ry="7" fill="#67816b"/>',dyson:'<path d="M91 133l65-86" stroke="#8fa17c" stroke-width="9"/><path d="M73 139l31 22 14-18-31-22z" fill="#647c5e"/><path d="M146 43l20-25 25 18-19 26z" fill="#87957a"/><path d="M145 29l20 14 9-12-20-14z" fill="#b7c398"/><path d="M167 53l19 12 7-12-17-10" fill="none" stroke="#4e6c51" stroke-width="7"/>',xiaomi:'<path d="M81 63h76l7 80c0 10-92 10-91 0z" fill="#fcfdf9" stroke="#aebda3" stroke-width="2"/><path d="M157 73h15c22 0 22 54-10 53" fill="none" stroke="#8fa080" stroke-width="8"/><path d="M81 64l-15-13 17 3" fill="#e4eadd" stroke="#aebda3" stroke-width="2"/><path d="M83 61q36-13 73 0" fill="#c9d3be"/><rect x="107" y="47" width="25" height="8" rx="4" fill="#78916c"/><path d="M68 154h102" stroke="#7c926e" stroke-width="7" stroke-linecap="round"/>'};return '<svg viewBox="0 0 240 180" width="180" height="130" aria-hidden="true">'+drawings[key]+'</svg>'}
const products=[{key:'airpods',label:'AirPods Pro 2',regex:/airpods\s*pro\s*2|苹果.*pro\s*2/i,name:'Apple AirPods Pro 2',spec:'USB-C 版 · 标准套装 · 1 件',icon:'♬',base:1399},{key:'dyson',label:'戴森 V12',regex:/(?:戴森|dyson)\s*v12|^v12$/i,name:'戴森 V12 吸尘器',spec:'Detect Slim · 标准套装 · 1 件',icon:'╱',base:2499},{key:'xiaomi',label:'小米电热水壶',regex:/小米.*水壶/i,name:'小米智能电热水壶',spec:'1.5L · 白色 · 1 件',icon:'♨',base:129}];
let compareQuery='AirPods Pro 2',condition='全新',newbie=false;
function renderCompare(){const enabled=state.platforms.filter(p=>p.enabled);$('#app').innerHTML=pageHead('FIND YOUR BETTER PRICE','心仪的好物，也可以好价入手。','同款、同规格，看清真正的到手价。')+`<div class="notice">✦ 演示模式：报价为固定模拟数据，不代表平台当前售价，也无法直接购买。支持下方 3 件示例商品。</div><div class="search-panel"><form id="compare-form" class="search-box"><input id="compare-query" aria-label="商品名称" value="${esc(compareQuery)}" placeholder="输入商品名、品牌或型号" required maxlength="100"><button type="submit" class="btn primary" ${compareLoading?'disabled':''}>${compareLoading?'查询中…':'⌕ 开始比价'}</button></form><div class="search-hints"><span>体验搜索</span>${products.map(p=>`<button class="chip" data-product="${p.key}">${p.label} ↗</button>`).join('')}</div><div class="search-options"><label>商品状态 <select id="condition"><option ${condition==='全新'?'selected':''}>全新</option><option ${condition==='二手'?'selected':''}>二手</option></select></label><label><input type="checkbox" id="newbie" style="width:auto" ${newbie?'checked':''}>我符合新人资格</label><span class="subtitle" style="font-size:10px">规格以结果卡片为准 · 运费按示例地区 ¥0 / ¥10</span></div></div><div id="compare-results"></div>`;$('#compare-form').onsubmit=e=>{e.preventDefault();runCompare()};$('#condition').onchange=e=>{condition=e.target.value;if(compareResult)runCompare()};$('#newbie').onchange=e=>{newbie=e.target.checked;if(compareResult)runCompare()};if(compareLoading)renderCompareLoading();else renderCompareResults();}
function renderCompareLoading(){$('#compare-results').innerHTML=`<div class="panel loading" style="margin-top:22px"><div class="spin">◌</div><h3>正在整理同款报价…</h3><p class="subtitle">核对规格、运费和优惠条件</p><div class="progress"><div></div></div><div class="platform-chips" style="justify-content:center">${state.platforms.filter(p=>p.enabled).map(p=>`<span class="chip">${esc(p.name)} · 模拟查询</span>`).join('')}</div></div>`}
function runCompare(){compareQuery=$('#compare-query').value.trim();if(!compareQuery)return;condition=$('#condition').value;newbie=$('#newbie').checked;const token=++searchCounter;compareLoading=true;renderCompare();setTimeout(()=>{if(token!==searchCounter)return;const product=products.find(p=>p.regex.test(compareQuery));compareResult={product,query:compareQuery,condition,newbie,platforms:state.platforms.filter(p=>p.enabled).map(p=>({...p})),time:new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'}),at:Date.now()};compareLoading=false;if(currentPage()==='compare')renderCompare()},1100)}
function renderCompareResults(){const el=$('#compare-results');if(!compareResult){el.innerHTML=`<div class="panel empty" style="margin-top:22px;padding:65px"><div style="font:48px var(--serif);color:#a8b89c">⌕</div><strong>找到好物，也找到好价格。</strong><p>选择一个示例商品，体验多平台比价流程。</p><div class="platform-chips" style="justify-content:center;margin-top:25px">${state.platforms.map(p=>`<span class="chip">${esc(p.name)} · ${p.enabled?'演示可用':'已停用'}</span>`).join('')}</div></div>`;return}
const r=compareResult,p=r.product;if(!r.platforms.length){el.innerHTML=`<div class="panel empty" style="margin-top:22px"><strong>还没有启用的平台</strong><p>前往平台管理，启用至少两个演示平台。</p><button class="btn" data-action="go-platforms">管理平台</button></div>`;return}if(!p){el.innerHTML=`<div class="panel empty" style="margin-top:22px"><strong>暂无“${esc(r.query)}”的演示报价</strong><p>原型没有真实电商接口。请体验 AirPods Pro 2、戴森 V12 或小米电热水壶。</p></div>`;return}
const available=r.platforms.filter(x=>r.condition==='二手'?x.type==='二手':x.type==='全新');let offers=available.map(x=>{const delta={pdd:-100,taobao:-80,jd:0,dewu:30,xianyu:-500}[x.id]??-20;const base=Math.max(19,p.base+(p.base<200?Math.round(delta/10):delta));const shipping=x.id==='taobao'||x.type==='二手'?10:0;const discount=x.id==='pdd'?(p.base<200?10:50):0;const isNew=x.id==='taobao';return {platform:x,base,shipping,discount,isNew,total:base+shipping-discount-(isNew&&r.newbie?(p.base<200?10:100):0)}}).sort((a,b)=>a.total-b.total);const success=offers.length,lowest=offers[0]?.total;el.innerHTML=`<div class="result-head"><div><h2>${esc(p.name)} <span class="pill">${esc(r.condition)}</span></h2><p>模拟查询 ${r.platforms.length} 个平台 · ${success} 个有报价 · ${r.platforms.length-success} 个不支持当前新旧条件</p></div><button class="btn small" data-action="refresh-comparison">↻ 重新查询</button></div><div class="platform-status">${r.platforms.map(x=>`<span>${esc(x.name)}：${available.some(a=>a.id===x.id)?'✓ 模拟成功':'— 无相应类型报价'}</span>`).join('')}</div>${success===1?'<div class="notice warn" style="margin-top:15px">仅一个平台有有效报价，暂不能完成跨平台比较。</div>':''}${!success?'<div class="panel empty" style="margin-top:20px"><strong>暂无符合条件的报价</strong>试试切换新旧状态，或启用相应类型平台。</div>':`<div class="offers" style="margin-top:18px">${offers.map((o,i)=>`<article class="offer ${i===0&&success>1?'best':''}">${i===0&&success>1?'<div class="best-ribbon">✓ 本次示例平台内最低已确认到手价</div>':'<div style="height:30px"></div>'}<div class="offer-body"><div class="product-art">${productArt(p.key)}</div><div class="platform-brand"><span class="platform-logo">${esc(o.platform.short)}</span>${esc(o.platform.name)} · 示例店铺</div><h3>${esc(p.name)}</h3><p class="spec">${esc(p.spec)}<br>${r.condition==='二手'?'九成新 · 配件齐全 · 保修需确认':'全新 · 示例保修条件一致'}</p><div class="offer-price">¥${money(o.total)}<small>模拟到手价</small></div><div class="price-line"><span>商品价</span><span>¥${money(o.base)}</span></div><div class="price-line"><span>运费 / 服务费</span><span>¥${money(o.shipping)} / ¥0.00</span></div><div class="price-line"><span>通用优惠</span><span>− ¥${money(o.discount)}</span></div>${o.isNew?`<div class="price-line"><span>${r.newbie?'已启用新人优惠':'新人条件价（不参与当前排序）'}</span><span>${r.newbie?'− ¥'+(p.base<200?'10.00':'100.00'):'¥'+money(o.base+o.shipping-(p.base<200?10:100))}</span></div>`:''}<button class="btn ${i===0?'primary':''}" data-offer="${o.platform.id}">查看模拟报价详情 ↗</button><p class="offer-time">示例采集时间 ${today} ${r.time} · 无真实购买链接</p></div></article>`).join('')}</div><p class="text-note">ⓘ 价格仅用于演示计算与排序，不是实时平台价格。${r.condition==='二手'?'二手仅比较示例中相同成色与配件条件。':''}</p>`}`;}
function renderPlatforms(){$('#app').innerHTML=pageHead('PLATFORM WORKSPACE','把选择权，放在自己手里。','维护参与比价的平台，了解每个平台的数据能力。',`<button class="btn primary" data-action="new-platform">＋ 添加平台</button>`)+`<div class="notice">当前全部为模拟适配器，启用仅影响示例查询范围。新增平台不会自动获得真实报价；正式接入需完成数据授权和适配器开发。</div><div class="stats"><div class="stat"><span class="label">候选平台</span><div class="value">${state.platforms.length}<small>个</small></div><p>统一维护平台配置</p></div><div class="stat"><span class="label">演示已启用</span><div class="value">${state.platforms.filter(p=>p.enabled).length}<small>个</small></div><p>参与模拟商品查询</p></div><div class="stat"><span class="label">真实接入</span><div class="value">0<small>个</small></div><p>后续需接入正式接口</p></div></div><div class="panel"><div class="panel-head"><h2>电商平台表单 <small>PLATFORM CONNECTIONS</small></h2><span class="pill amber">原型管理员视图</span></div><div class="table-scroll"><table class="platform-table"><thead><tr><th>平台</th><th>商品范围</th><th>数据能力</th><th>接入状态</th><th>演示启用</th><th>管理</th></tr></thead><tbody>${state.platforms.map(p=>`<tr><td><div class="asset-cell"><span class="platform-logo">${esc(p.short)}</span><span><b>${esc(p.name)}</b><small>${esc(p.id)}</small></span></div></td><td>${esc(p.type)}</td><td><span style="font-size:10px;color:#87947c">${esc(p.note)}</span></td><td><span class="pill gray">${p.tested?'模拟测试已通过':'真实接口待接入'}</span></td><td><button class="switch ${p.enabled?'on':''}" data-toggle-platform="${p.id}" role="switch" aria-checked="${p.enabled}" aria-label="${esc(p.name)} 演示启用"></button></td><td><button class="link" data-edit-platform="${p.id}">编辑</button> <button class="link" data-test-platform="${p.id}">测试</button></td></tr>`).join('')}</tbody></table></div></div><div class="tip" style="margin-top:22px"><h3>✦ 价格比较，也需要相同的起点。</h3><p>全新与二手分开比较；只有规格、运费和优惠条件清楚的商品才能进入默认最低价。平台越多，选择越多，但可核验的报价更重要。</p></div>`}
function platformForm(id){const p=state.platforms.find(p=>p.id===id)||{id:'',name:'',type:'全新',note:'模拟报价 · 自定义平台',enabled:false};openModal(id?'编辑平台':'添加候选平台',`<form id="platform-form"><div class="dialog-body"><div class="field"><label for="pname">平台名称</label><input id="pname" name="name" value="${esc(p.name)}" maxlength="20" required></div><div class="field"><label for="pid">平台 ID</label><input id="pid" name="id" value="${esc(p.id)}" placeholder="例如：suning" pattern="[a-z][a-z0-9_-]{1,29}" ${id?'readonly':''} required><small>2–30 位小写英文、数字、下划线或短横线；创建后不可更改</small></div><div class="field"><label for="ptype">支持商品</label><select id="ptype" name="type"><option ${p.type==='全新'?'selected':''}>全新</option><option ${p.type==='二手'?'selected':''}>二手</option></select></div><div class="field"><label for="pnote">能力说明</label><input id="pnote" name="note" value="${esc(p.note)}" maxlength="80" required></div><div class="notice">适配器：模拟数据（只用于原型体验）<br>此表单不收集 API 密钥，不会建立真实平台连接。</div><div class="error" id="platform-error" role="alert"></div></div><div class="dialog-foot"><button type="button" class="btn" data-action="close">取消</button><button type="submit" class="btn primary">保存平台</button></div></form>`);$('#platform-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim())return $('#platform-error').textContent='请输入平台名称';if(!id&&state.platforms.some(p=>p.id===f.id))return $('#platform-error').textContent='平台 ID 已存在';const next={...p,...f,name:f.name.trim(),short:f.name.trim().slice(0,1)};if(id)state.platforms=state.platforms.map(x=>x.id===id?next:x);else state.platforms.push(next);save();closeModal();renderPlatforms();toast('已保存候选平台')};}
function exportAssets(){const safe=s=>'"'+String(s??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['名称','分类','买入总价','退款','净成本','开始使用日','结束日','状态','日均成本'],...state.assets.map(a=>[a.name,a.category,a.price,a.refund||0,net(a),a.start,a.end||'',a.status,a.status==='未启用'?'':daily(a).toFixed(2)])];download('生活资产-'+today+'.csv',rows.map(r=>r.map(safe).join(',')).join('\r\n'));toast('资产清单已导出')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.asset)return assetDetail(d.asset);if(d.editAsset)return assetForm(d.editAsset);if(d.deleteAsset){const id=d.deleteAsset;openModal('删除这件资产？',`<div class="dialog-body"><p>将从本地清单中移除此物品，汇总成本随之更新。此操作无法撤销。</p></div>`,`<button class="btn" data-action="close">取消</button><button class="btn danger" data-confirm-delete="${id}">确认删除</button>`);return}if(d.confirmDelete){state.assets=state.assets.filter(a=>a.id!==d.confirmDelete);save();closeModal();render();return toast('资产已删除')}if(d.filter){activeFilter=d.filter;renderAssets();return}if(d.product){const p=products.find(p=>p.key===d.product);$('#compare-query').value=p.label;runCompare();return}if(d.offer){const p=state.platforms.find(p=>p.id===d.offer);openModal('模拟报价详情',`<div class="dialog-body"><span class="pill amber">固定示例数据</span><h3>${esc(compareResult.product.name)}</h3><p>平台：${esc(p?.name||'示例平台')}</p><p class="subtitle">${esc(compareResult.product.spec)}</p><div class="notice warn" style="margin-top:20px">原型尚未连接真实电商平台，因此没有实际购买链接。正式版本将在这里打开对应平台的真实商品页，并显示采集时间和适用条件。</div></div>`,`<button class="btn primary" data-action="close">知道了</button>`);return}if(d.togglePlatform){const p=state.platforms.find(p=>p.id===d.togglePlatform);p.enabled=!p.enabled;save();renderPlatforms();return toast(p.name+(p.enabled?'已加入模拟查询':'已停止参与查询'))}if(d.editPlatform)return platformForm(d.editPlatform);if(d.testPlatform){b.disabled=true;b.textContent='测试中…';setTimeout(()=>{const p=state.platforms.find(p=>p.id===d.testPlatform);p.tested=true;save();if(currentPage()==='platforms')renderPlatforms();toast('模拟适配器响应正常，真实接口仍未接入')},700);return}
switch(d.action){case 'close':closeModal();break;case 'new-asset':assetForm();break;case 'go-import':go('import');break;case 'go-assets':activeFilter='在用';go('assets');break;case 'go-compare':go('compare');break;case 'go-platforms':go('platforms');break;case 'export-assets':exportAssets();break;case 'choose-file':$('#bill-file').click();break;case 'demo-import':prepareImport(demoBill(),'示例生活账单.csv');break;case 'download-template':download('账单导入模板.csv',`交易号,交易时间,商品名称,金额,类型,分类\nMY-001,${today},我的台灯,199,资产,家用电器\nMY-002,${today},午餐,32,消费,其他`);break;case 'new-import':importRows=null;importDone=null;renderImport();break;case 'confirm-import':confirmImport();break;case 'download-errors':download('导入处理报告.csv','行号,商品,处理结果\n'+importRows.map(r=>[r.row,'"'+r.name.replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"','"'+(r.error|| (r.duplicate?'重复':r.kind)).replaceAll('"','""')+'"'].join(',')).join('\n'));break;case 'refresh-comparison':runCompare();break;case 'new-platform':platformForm();break;}});
document.addEventListener('change',e=>{if(e.target.dataset.importRow!==undefined){const r=importRows[Number(e.target.dataset.importRow)];r.kind=e.target.value;renderImport()}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
document.addEventListener('keydown',e=>{if($('#modal').hidden)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const f=$$('button,input,select,[href]', $('#modal')).filter(x=>!x.disabled),first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
$('#reset').onclick=()=>openModal('重新开始体验？',`<div class="dialog-body"><p>将清空当前浏览器中的手动修改和导入记录，恢复初始示例数据。</p></div>`,`<button class="btn" data-action="close">取消</button><button class="btn danger" id="reset-confirm">恢复示例数据</button>`);
document.addEventListener('click',e=>{if(e.target.id==='reset-confirm'){state={assets:seedAssets(),platforms:seedPlatforms(),imported:[],history:[]};save();importRows=null;importDone=null;compareResult=null;compareLoading=false;searchCounter++;activeFilter='在用';assetQuery='';closeModal();render();toast('已恢复初始示例')}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
